import json

def _first_wins(pairs):
    d = {}
    for k, v in pairs:
        if k not in d:
            d[k] = v
    return d

def validate(raw):
    # Security gate: reject anything asking for the admin role. Uses a scan
    # that honours the FIRST occurrence of a duplicated key.
    obj = json.loads(raw, object_pairs_hook=_first_wins)
